import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';

const Navbar = () => {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed top-0 w-full z-50 transition-all duration-300 ${scrolled ? 'bg-white/90 backdrop-blur-md shadow-lg py-3' : 'bg-transparent py-5'}`}>
      <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">
        <Link to="/" className="flex items-center space-x-2">
          <div className="w-10 h-10 bg-gradient-to-br from-emerald-600 to-teal-500 rounded-lg flex items-center justify-center text-white font-bold text-xl">L</div>
          <span className={`text-2xl font-bold font-poppins ${scrolled ? 'text-slate-900' : 'text-white'}`}>LawBridge</span>
        </Link>

        <div className="hidden md:flex space-x-8 items-center">
          <Link to="/" className={`nav-link ${scrolled ? 'text-slate-700' : 'text-white/90'}`}>Home</Link>
          <Link to="/lawyers" className={`nav-link ${scrolled ? 'text-slate-700' : 'text-white/90'}`}>Lawyers</Link>
          <Link to="/documents" className={`nav-link ${scrolled ? 'text-slate-700' : 'text-white/90'}`}>Documents</Link>
          <Link to="/contact" className={`nav-link ${scrolled ? 'text-slate-700' : 'text-white/90'}`}>Contact</Link>
          <Link to="/signup" className="btn-gradient">
            Get Started
          </Link>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
